{"implementation":"import json
def solve(case):
    # Extract required fields
    wti = case.get('word_token_indices')
    wl = case.get('word_labels')
    tc = case.get('token_count')

    # Validate basic structure
    if not (isinstance(wti, list) and isinstance(wl, list) and isinstance(tc, int)):
        return {'error': 'invalid input types'}
    if len(wti) != len(wl):
        return {'error': 'mismatched word groups and labels'}
    if tc < 0:
        return {'error': 'negative token count'}

    # Flatten all indices to check coverage and overlap
    all_indices = []
    seen = set()
    for group in wti:
        if not isinstance(group, list):
            return {'error': 'invalid token index group'}
        for idx in group:
            if not isinstance(idx, int) or idx < 0 or idx >= tc:
                return {'error': 'out-of-range token index'}
            if idx in seen:
                return {'error': 'overlapping token indices'}
            seen.add(idx)
            all_indices.append(idx)

    # Check uncovered tokens (all indices from 0 to tc-1 must appear exactly once)
    expected = set(range(tc))
    if seen != expected:
        return {'error': 'uncovered token indices'}

    # Build token labels
    token_labels = [0] * tc
    for group, label in zip(wti, wl):
        # Validate label is int 0 or 1
        if label not in (0, 1):
            return {'error': 'invalid word label'}
        for idx in group:
            token_labels[idx] = label

    # Retained indices
    retained = [i for i, lbl in enumerate(token_labels) if lbl == 1]

    return {
        'token_labels': token_labels,
        'retained_indices': retained
    }"}
